\u0430\\u043b\\u0438\\u0441\\u044c \\u0447\\u0438\\u0441\\u0442\\u044b\\u043c\\u0438.<\\/p>\\n<p>\\u041c\\u043e\\u0441\\u043a\\u0432\\u0430 \\u043e\\u0447\\u0435\\u043d\\u044c \\u0431\\u043e\\u043b\\u044c\\u0448\\u043e\\u0439 \\u0433\\u043e\\u0440\\u043e\\u0434, \\u0433\\u0434\\u0435 \\u0435\\u0441\\u0442\\u044c \\u043e\\u0433\\u0440\\u043e\\u043c\\u043d\\u043e\\u0435 \\u043a\\u043e\\u043b\\u0438\\u0447\\u0435\\u0441\\u0442\\u0432\\u043e \\u043c\\u0435\\u0441\\u0442 \\u043f\\u0440\\u043e\\u0434\\u0430\\u0436\\u0438 \\u0433\\u0438\\u0433\\u0438\\u0435\\u043d\\u0438\\u0447\\u0435\\u0441\\u043a\\u0438\\u0445 \\u043f\\u0440\\u0438\\u0441\\u043f\\u043e\\u0441\\u043e\\u0431\\u043b\\u0435\\u043d\\u0438\\u0439. \\u041d\\u043e \\u0442\\u043e\\u043b\\u044c\\u043a\\u043e \\u0443 \\u043d\\u0430\\u0441 \\u0441\\u0430\\u043c\\u0430\\u044f \\u043d\\u0438\\u0437\\u043a\\u0430\\u044f \\u0446\\u0435\\u043d\\u0430 \\u0438 \\u0441\\u0430\\u043c\\u043e\\u0435 \\u0432\\u044b\\u0441\\u043e\\u043a\\u043e\\u0435 \\u043a\\u0430\\u0447\\u0435\\u0441\\u0442\\u0432\\u043e. \\u0417\\u0430\\u0445\\u043e\\u0434\\u0438\\u0442\\u0435 \\u0432 \\u043d\\u0430\\u0448 \\u0438\\u043d\\u0442\\u0435\\u0440\\u043d\\u0435\\u0442-\\u043c\\u0430\\u0433\\u0430\\u0437\\u0438\\u043d \\u0438 \\u0443\\u0431\\u0435\\u0434\\u0438\\u0442\\u0435\\u0441\\u044c \\u043d\\u0430 \\u043b\\u0438\\u0447\\u043d\\u043e\\u043c \\u043e\\u043f\\u044b\\u0442\\u0435 \\u0432 \\u043a\\u0430\\u0447\\u0435\\u0441\\u0442\\u0432\\u0435 \\u043f\\u0440\\u0435\\u0434\\u043b\\u0430\\u0433\\u0430\\u0435\\u043c\\u043e\\u0439 \\u043f\\u0440\\u043e\\u0434\\u0443\\u043a\\u0446\\u0438\\u0438. \\u0417\\u0430\\u043a\\u0430\\u0437\\u0430\\u0442\\u044c \\u0442\\u043e\\u0432\\u0430\\u0440, \\u043a\\u043e\\u0442\\u043e\\u0440\\u044b\\u0439 \\u0432\\u0430\\u043c \\u043f\\u043e\\u043d\\u0440\\u0430\\u0432\\u0438\\u043b\\u0441\\u044f \\u043e\\u0447\\u0435\\u043d\\u044c \\u043f\\u0440\\u043e\\u0441\\u0442\\u043e. \\u0414\\u043e\\u0441\\u0442\\u0430\\u0442\\u04