\u0440\\u0430\\u0441\\u0445\\u043e\\u0434\\u043e\\u0432\\u0430\\u043b\\u0430 \\u0432 2017 \\u0433. \\u043d\\u0430 \\u043f\\u0440\\u0438\\u0440\\u043e\\u0434\\u043e\\u043e\\u0445\\u0440\\u0430\\u043d\\u043d\\u044b\\u0435 \\u043c\\u0435\\u0440\\u043e\\u043f\\u0440\\u0438\\u044f\\u0442\\u0438\\u044f \\u043f\\u043e\\u0447\\u0442\\u0438 32 \\u043c\\u043b\\u0440\\u0434 \\u0440\\u0443\\u0431\\u043b\\u0435\\u0439 \\u2014 \\u043f\\u043e \\u0441\\u0440\\u0435\\u0434\\u043d\\u0435\\u0433\\u043e\\u0434\\u043e\\u0432\\u043e\\u043c\\u0443 \\u043a\\u0443\\u0440\\u0441\\u0443 \\u044d\\u0442\\u043e \\u0431\\u043e\\u043b\\u044c\\u0448\\u0435 \\u043f\\u043e\\u043b\\u0443\\u043c\\u0438\\u043b\\u043b\\u0438\\u0430\\u0440\\u0434\\u0430 \\u0434\\u043e\\u043b\\u043b\\u0430\\u0440\\u043e\\u0432.<\\/p>\\n<p class=\\\"ntext\\\">\\u041a\\u0430\\u043a \\u0441\\u043b\\u0435\\u0434\\u0443\\u0435\\u0442 \\u0438\\u0437 \\u0440\\u0435\\u0439\\u0442\\u0438\\u043d\\u0433\\u0430, \\u0431\\u043e\\u043b\\u044c\\u0448\\u0435 \\u0432\\u0441\\u0435\\u0445 \\u043d\\u0430 \\u0441\\u043e\\u0445\\u0440\\u0430\\u043d\\u0435\\u043d\\u0438\\u0435 \\u0438 \\u0432\\u043e\\u0441\\u0441\\u0442\\u0430\\u043d\\u043e\\u0432\\u043b\\u0435\\u043d\\u0438\\u0435 \\u043f\\u0440\\u0438\\u0440\\u043e\\u0434\\u044b \\u0442\\u0440\\u0430\\u0442\\u044f\\u0442\\u0441\\u044f \\u043d\\u0435\\u0444\\u0442\\u044f\\u043d\\u044b\\u0435, \\u043c\\u0435\\u0442\\u0430\\u043b\\u043b\\u0443\\u0440\\u0433\\u0438\\u0447\\u0435\\u0441\\u043a\\u0438\\u0435 \\u043a\\u043e\\u043c\\u043f\\u0430\\u043d\\u0438\\u0438 \\u0438 \\u043f\\u0440\\u0435\\u0434\\u0441\\u0442\\u0430\\u0432\\u0438\\u0442\\u0435\\u043b\\u0438 \\u0446\\u0435\\u043b\\u043b\\u044e\\u043b\\u043e\\u0437\\u043d\\u043e-\\u0431\\u0443\\u043c\\u0430\\u0436\\u043d\\u043e\\u0439 \\u043f\\u0440\\u043e\\u043c\\u044b\\u0448\\u043b\\u0435\\u043d\\u043d\\u043e\\u0441\\u0442\\u0438. \\u0412 \\u0446\\u0435\\u043b\\u043e\\u043c \\u043f\\u043e \\u0441\\u0442\\u0440\\u0430\\u043d\\u0435 \\u043f\\u04