u043d\\u0435\\u0446 \\u0433\\u043e\\u0440\\u0430\\u0437\\u0434\\u043e \\u0432\\u044b\\u0448\\u0435. 1-\\u0441\\u043b\\u043e\\u0439\\u043d\\u044b\\u0435 \\u043f\\u043e\\u043b\\u043e\\u0442\\u0435\\u043d\\u0446\\u0430 \\u043d\\u0435 \\u0442\\u0430\\u043a\\u0438\\u0435 \\u043f\\u0440\\u043e\\u0447\\u043d\\u044b\\u0435.<\\/p>\\n<p>\\u0412 \\u043f\\u0440\\u043e\\u0434\\u0430\\u0436\\u0435 \\u043f\\u0440\\u0435\\u0434\\u0441\\u0442\\u0430\\u0432\\u043b\\u0435\\u043d\\u044b \\u043f\\u043e\\u043b\\u043e\\u0442\\u0435\\u043d\\u0446\\u0430, \\u043a\\u043e\\u0442\\u043e\\u0440\\u044b\\u0435 \\u043d\\u0430\\u0445\\u043e\\u0434\\u044f\\u0442\\u0441\\u044f \\u043d\\u0430 \\u0433\\u0438\\u043b\\u044c\\u0437\\u0435. \\u041e\\u043d\\u0438 \\u043b\\u0443\\u0447\\u0448\\u0435 \\u0432\\u0441\\u0435\\u0433\\u043e \\u043f\\u043e\\u0434\\u0445\\u043e\\u0434\\u044f\\u0442 \\u0434\\u043b\\u044f \\u043a\\u0443\\u0445\\u043d\\u0438. \\u0420\\u0443\\u043b\\u043e\\u043d\\u044b \\u043f\\u043e\\u043b\\u043e\\u0442\\u0435\\u043d\\u0435\\u0446 \\u0438\\u043c\\u0435\\u044e\\u0442 \\u0441\\u043f\\u0435\\u0446\\u0438\\u0430\\u043b\\u044c\\u043d\\u044b\\u0435 \\u043c\\u0435\\u0441\\u0442\\u0430 \\u0434\\u043b\\u044f \\u043e\\u0431\\u0440\\u044b\\u0432\\u0430, \\u0447\\u0442\\u043e \\u0434\\u0435\\u043b\\u0430\\u0435\\u0442 \\u0438\\u0445 \\u0435\\u0449\\u0435 \\u0431\\u043e\\u043b\\u0435\\u0435 \\u0443\\u0434\\u043e\\u0431\\u043d\\u044b\\u043c\\u0438 \\u0432 \\u043f\\u0440\\u0438\\u043c\\u0435\\u043d\\u0435\\u043d\\u0438\\u0438, \\u0432\\u0435\\u0434\\u044c \\u043f\\u043e\\u043b\\u043e\\u0442\\u0435\\u043d\\u0446\\u0430 \\u043e\\u0442\\u043b\\u0438\\u0447\\u043d\\u043e \\u043e\\u0442\\u0434\\u0435\\u043b\\u044f\\u044e\\u0442\\u0441\\u044f. \\u0422\\u0430\\u043a\\u0436\\u0435 \\u0441\\u0442\\u043e\\u0438\\u0442 \\u043e\\u0431\\u0440\\u0430\\u0442\\u0438\\u0442\\u044c \\u0432\\u043d\\u0438\\u043c\\u0430\\u043d\\u0438\\u0435 \\u043d\\u0430 \\u043b\\u0438\\u0441\\u0442\\u043e\\u0432\\u044b\\u0435 \\u0431\\